"""Generates the small DEMO dataset ml/data/seed_emails.csv from templates (synthetic, for first-run only).
Replace with a real dataset by saving it as ml/data/emails.csv and running: python -m ml.train"""
import csv, os, random
R = random.Random(7); P = R.choice
N = ["Priya", "Arun", "Meena", "Karthik", "Sara", "David", "Anita", "Rahul"]
TOPIC = ["the Q3 report", "the lab assignment", "the project proposal", "next week's schedule", "the budget sheet", "the design review"]
SAFE = [lambda: P(["Meeting notes", "Question about {t}", "Lunch tomorrow?", "Update on {t}", "Thanks for your help", "Draft of {t} attached"]).format(t=P(TOPIC)),
  lambda: f"Hi {P(N)}, " + P(["just sharing the notes from today's meeting.", "could you review {t} before Friday?", "thanks for sending {t}, it looks good to me.", "are we still meeting at 3 pm to discuss {t}?", "I have uploaded {t} to the shared drive."]).format(t=P(TOPIC)) + " " + P(["Let me know if you have questions.", "See you tomorrow.", "Regards, " + P(N), "Thanks!"]) + P(["", "", " Link: https://docs.google.com/document/d/" + str(R.randint(100, 999)), " https://github.com/team/project/issues/" + str(R.randint(1, 99))])]
SPAM = [lambda: P(["You have WON a free {x}!!!", "Huge discount: 80% off today only", "Lose weight fast with this miracle pill", "Make $5000 a week from home", "Cheap meds, no prescription needed", "Congratulations winner, claim your prize"]).format(x=P(["iPhone", "gift card", "cruise", "laptop"])),
  lambda: P(["Dear friend, ", "Hello!!! ", "Limited offer! "]) + P(["Buy now and get a free bonus gift.", "You are our lucky winner, claim your free prize today.", "Click here for the best casino bonus and win big money.", "Earn easy money working from home, no experience needed.", "Order cheap pills online with fast shipping and huge discounts."]) + " " + P(["Unsubscribe anytime.", "Act now, offer ends tonight!!!", "100% guaranteed, risk free."]) + " " + P(["http://cheap-deals" + str(R.randint(1, 99)) + ".example/offer", "https://bit.ly/" + str(R.randint(1000, 9999)), "www.winbig-" + str(R.randint(1, 99)) + ".example"])]
PHISH = [lambda: P(["Your {b} account has been suspended", "Action required: verify your {b} account", "Unusual sign-in attempt detected on your {b} account", "Your {b} password expires today", "Security alert: confirm your identity", "Payment failed for your {b} subscription"]).format(b=P(["PayPal", "Amazon", "Microsoft", "bank", "Netflix", "Apple"])),
  lambda: P(["Dear customer, ", "Dear user, ", "Attention: "]) + P(["we detected suspicious activity on your account. Please verify your identity immediately to avoid suspension.", "your password will expire within 24 hours. Confirm your login details now to keep access.", "your payment could not be processed. Update your billing information and card details to restore service.", "your package could not be delivered. Pay the small customs fee and confirm your address.", "your mailbox is full. Sign in to validate your account and avoid permanent closure."]) + " " + P(["Click the link below: ", "Log in here: ", "Verify now: "]) + P(["http://secure-paypa1-login.example/verify?id=", "http://192.168.%d.%d/signin?acct=" % (R.randint(1, 99), R.randint(1, 99)), "http://account-update-microsoft.example/login/", "https://tinyurl.com/", "http://amazon-security-check.example/confirm/"]) + str(R.randint(100, 999))]
rows = [(s(), b(), l) for l, (s, b) in [("safe", SAFE), ("spam", SPAM), ("phishing", PHISH)] for _ in range(200)]
R.shuffle(rows)
with open(os.path.join(os.path.dirname(__file__), "data", "seed_emails.csv"), "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f); w.writerow(["subject", "message", "label"]); w.writerows(rows)
